          "id": "code-ml-06-1-ch06_1_scratch",
          "title": "First-Principles NumPy: Normal Equations vs QR/SVD & Proyeksi Ortogonal",
          "language": "python",
          "filename": "06_1_ols_qr_svd_projection.py",
          "code": "import numpy as np\n\n# 1. Uji Stabilitas Numerik: Normal Equations vs QR vs SVD pada Matriks Ill-Conditioned (Lauchli)\neps = 2e-8\n# Matriks Lauchli 5x4: kappa(X) ~ 1e8, sedangkan kappa(X^T X) ~ 1e16 (batas presisi FP64!)\nX_ill = np.array([\n    [1.0, 1.0, 1.0, 1.0],\n    [eps, 0.0, 0.0, 0.0],\n    [0.0, eps, 0.0, 0.0],\n    [0.0, 0.0, eps, 0.0],\n    [0.0, 0.0, 0.0, eps],\n], dtype=np.float64)\nbeta_true = np.array([1.0, -2.0, 3.0, -1.5], dtype=np.float64)\n# Tambahkan sedikit komponen ortogonal terhadap kolom X (seperti residual data nyata)\nQ_tmp, _ = np.linalg.qr(X_ill, mode=\"complete\")\nr_orth = 0.25 * Q_tmp[:, -1]\ny_ill = X_ill @ beta_true + r_orth\n\nkappa_X = float(np.linalg.cond(X_ill))\nkappa_XtX = float(np.linalg.cond(X_ill.T @ X_ill))\n\n# Metode A: Normal Equations langsung (mengkuadratkan condition number -> kolaps!)\nbeta_ne = np.linalg.solve(X_ill.T @ X_ill, X_ill.T @ y_ill)\n\n# Metode B: Dekomposisi QR (Householder)\nQ, R = np.linalg.qr(X_ill, mode=\"reduced\")\nbeta_qr = np.linalg.solve(R, Q.T @ y_ill)\n\n# Metode C: Dekomposisi SVD (basis scipy/sklearn LinearRegression)\nU, s, Vt = np.linalg.svd(X_ill, full_matrices=False)\nbeta_svd = Vt.T @ ((U.T @ y_ill) / s)\n\nprint(\"=== Audit Stabilitas Numerik OLS pada Matriks Lauchli (eps=2e-8) ===\")\nprint(f\"Condition Number kappa(X)      = {kappa_X:.2e}\")\nprint(f\"Condition Number kappa(X^T X)  = {kappa_XtX:.2e} (~ kappa(X)^2)\")\nprint(f\"Galat ||beta_NE  - beta*||_2   = {np.linalg.norm(beta_ne - beta_true):.3e}  <-- hancur!\")\nprint(f\"Galat ||beta_QR  - beta*||_2   = {np.linalg.norm(beta_qr - beta_true):.3e}\")\nprint(f\"Galat ||beta_SVD - beta*||_2   = {np.linalg.norm(beta_svd - beta_true):.3e}\")\n\n# 2. Verifikasi Geometri Proyeksi Ortogonal & Teorema Pythagoras\nrng = np.random.default_rng(42)\nn, p = 120, 4\nX = np.column_stack([np.ones(n), rng.normal(0.0, 1.0, size=(n, p - 1))])\ny = X @ np.array([2.0, 1.5, -0.8, 0.6]) + rng.normal(0.0, 1.2, size=n)\n\nQ_g, R_g = np.linalg.qr(X, mode=\"reduced\")\nP = Q_g @ Q_g.T  # Matriks proyektor ortogonal P = X(X^T X)^{-1} X^T\ny_hat = P @ y\nresid = y - y_hat\n\nprint(\"--- Verifikasi Geometri Proyeksi Ortogonal ---\")\nprint(f\"Idempoten ||P^2 - P||_F        = {np.linalg.norm(P @ P - P):.2e}\")\nprint(f\"Simetri   ||P^T - P||_F        = {np.linalg.norm(P.T - P):.2e}\")\nprint(f\"Trace(P)  (harus = p={p})        = {np.trace(P):.1f}\")\nprint(f\"Ortogonalitas ||X^T e||_2      = {np.linalg.norm(X.T @ resid):.2e}\")\nprint(f\"Pythagoras | ||y||^2 - (||yhat||^2 + ||e||^2) | = {abs(np.dot(y, y) - (np.dot(y_hat, y_hat) + np.dot(resid, resid))):.2e}\")",
          "expectedOutput": "=== Audit Stabilitas Numerik OLS pada Matriks Lauchli (eps=2e-8) ===\nCondition Number kappa(X)      = 1.00e+08\nCondition Number kappa(X^T X)  = 1.03e+16 (~ kappa(X)^2)\nGalat ||beta_NE  - beta*||_2   = 3.536e-01  <-- hancur!\nGalat ||beta_QR  - beta*||_2   = 2.168e-09\nGalat ||beta_SVD - beta*||_2   = 3.969e-09\n--- Verifikasi Geometri Proyeksi Ortogonal ---\nIdempoten ||P^2 - P||_F        = 8.72e-16\nSimetri   ||P^T - P||_F        = 0.00e+00\nTrace(P)  (harus = p=4)        = 4.0\nOrtogonalitas ||X^T e||_2      = 1.22e-13\nPythagoras | ||y||^2 - (||yhat||^2 + ||e||^2) | = 5.68e-13",
          "actualOutput": "=== Audit Stabilitas Numerik OLS pada Matriks Lauchli (eps=2e-8) ===\nCondition Number kappa(X)      = 1.00e+08\nCondition Number kappa(X^T X)  = 1.03e+16 (~ kappa(X)^2)\nGalat ||beta_NE  - beta*||_2   = 3.536e-01  <-- hancur!\nGalat ||beta_QR  - beta*||_2   = 2.168e-09\nGalat ||beta_SVD - beta*||_2   = 3.969e-09\n--- Verifikasi Geometri Proyeksi Ortogonal ---\nIdempoten ||P^2 - P||_F        = 8.72e-16\nSimetri   ||P^T - P||_F        = 0.00e+00\nTrace(P)  (harus = p=4)        = 4.0\nOrtogonalitas ||X^T e||_2      = 1.22e-13\nPythagoras | ||y||^2 - (||yhat||^2 + ||e||^2) | = 5.68e-13",
