          "code": "import numpy as np\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.metrics import r2_score, root_mean_squared_error\n\nrng = np.random.default_rng(42)\nn_train, n_test = 100, 150\nn_total = n_train + n_test\n\n# Hanya 3 fitur sinyal sejati; sisanya murni derau Gaussian independen\nX_sig = rng.normal(0.0, 1.0, size=(n_total, 3))\nw_sig = np.array([3.0, -2.2, 1.8])\ny = 5.0 + X_sig @ w_sig + rng.normal(0.0, 2.0, size=n_total)\n\nX_sig_tr, X_sig_te = X_sig[:n_train], X_sig[n_train:]\ny_tr, y_te = y[:n_train], y[n_train:]\n\nprint(\"=== Mengapa In-Sample R^2 Menipu: Menambah Fitur Derau Murni (N_train=100, sigma=2.0) ===\")\nprint(f\"{'Noise Feat':>10s} | {'p_total':>7s} | {'R2_train':>8s} | {'Adj_R2':>8s} | {'R2_test':>9s} | {'RMSE_test':>9s}\")\nprint(\"-\" * 68)\n\nfor k_noise in (0, 15, 45, 75, 88):\n    if k_noise == 0:\n        Xtr, Xte = X_sig_tr, X_sig_te\n    else:\n        noise_tr = rng.normal(0.0, 1.0, size=(n_train, k_noise))\n        noise_te = rng.normal(0.0, 1.0, size=(n_test, k_noise))\n        Xtr = np.hstack([X_sig_tr, noise_tr])\n        Xte = np.hstack([X_sig_te, noise_te])\n\n    model = LinearRegression().fit(Xtr, y_tr)\n    pred_tr = model.predict(Xtr)\n    pred_te = model.predict(Xte)\n\n    r2_tr = r2_score(y_tr, pred_tr)\n    p = Xtr.shape[1]\n    adj_r2 = 1.0 - (1.0 - r2_tr) * (n_train - 1) / (n_train - p - 1)\n    r2_te = r2_score(y_te, pred_te)\n    rmse_te = root_mean_squared_error(y_te, pred_te)\n    print(f\"{k_noise:10d} | {p:7d} | {r2_tr:8.4f} | {adj_r2:8.4f} | {r2_te:9.4f} | {rmse_te:9.4f}\")",
          "expectedOutput": "=== Mengapa In-Sample R^2 Menipu: Menambah Fitur Derau Murni (N_train=100, sigma=2.0) ===\nNoise Feat | p_total | R2_train |   Adj_R2 |   R2_test | RMSE_test\n--------------------------------------------------------------------\n         0 |       3 |   0.7275 |   0.7190 |    0.7970 |    1.9795\n        15 |      18 |   0.7436 |   0.6867 |    0.7813 |    2.0548\n        45 |      48 |   0.8546 |   0.7178 |    0.6023 |    2.7710\n        75 |      78 |   0.9240 |   0.6418 |   -0.1933 |    4.7996\n        88 |      91 |   0.9749 |   0.6899 |   -4.8755 |   10.6503",
