          "id": "code-ml-06-1-ch06_1_diag",
          "title": "Monte Carlo BLUE Gauss-Markov (Non-Gaussian) & Range Inflation R^2",
          "language": "python",
          "filename": "06_1_gauss_markov_monte_carlo.py",
          "code": "import numpy as np\n\n# 1. Simulasi Monte Carlo Teorema Gauss-Markov (BLUE) dengan Error Non-Gaussian (Uniform)\nrng = np.random.default_rng(7)\nn = 80\nx = rng.uniform(-2.0, 2.0, size=n)\nX = np.column_stack([np.ones(n), x])\nbeta_true = np.array([1.5, 2.4])\n\n# Matriks proyeksi 3 estimator linear tak bias untuk slope beta_1:\n# (A) OLS: (X^T X)^{-1} X^T\nA_ols = np.linalg.pinv(X)\n# (B) Misaligned Weighted Linear Unbiased Estimator (W != I): (X^T W X)^{-1} X^T W\nw_mis = np.linspace(0.2, 4.0, n)\nW = np.diag(w_mis)\nA_wlu = np.linalg.solve(X.T @ W @ X, X.T @ W)\n# (C) Split-Half Wald Estimator (linear terhadap y, tak bias murni)\nmed = np.median(x)\nhi = (x >= med).astype(float)\nlo = (x < med).astype(float)\ndenom_wald = (hi @ x) / hi.sum() - (lo @ x) / lo.sum()\na_wald_slope = (hi / hi.sum() - lo / lo.sum()) / denom_wald\n\nn_trials = 2500\n# Error seragam [-sqrt(3), +sqrt(3)] -> mean=0, var=1.0, NON-GAUSSIAN!\nE = rng.uniform(-np.sqrt(3.0), np.sqrt(3.0), size=(n, n_trials))\nY = (X @ beta_true)[:, None] + E\n\nb1_ols = A_ols[1, :] @ Y\nb1_wlu = A_wlu[1, :] @ Y\nb1_wald = a_wald_slope @ Y\n\nvar_theo_ols = float(np.linalg.inv(X.T @ X)[1, 1])\n\nprint(\"=== Verifikasi Monte Carlo BLUE Gauss-Markov (2500 Trial, Error Uniform Non-Gaussian) ===\")\nprint(f\"Teoretis Var(beta1_OLS)   = {var_theo_ols:.6f}\")\nprint(f\"1. OLS (BLUE)             -> mean={b1_ols.mean():.4f} | emp_var={b1_ols.var(ddof=1):.6f} (ratio=1.00x)\")\nprint(f\"2. Weighted Linear Unbias -> mean={b1_wlu.mean():.4f} | emp_var={b1_wlu.var(ddof=1):.6f} (ratio={b1_wlu.var(ddof=1)/b1_ols.var(ddof=1):.2f}x)\")\nprint(f\"3. Wald Split-Half Linear -> mean={b1_wald.mean():.4f} | emp_var={b1_wald.var(ddof=1):.6f} (ratio={b1_wald.var(ddof=1)/b1_ols.var(ddof=1):.2f}x)\")\n\n# 2. Ilustrasi Range Inflation pada R^2 (RMSE identik, R^2 melompat drastis!)\nprint(\"--- Jebakan Range Inflation R^2 (Slope=1.5, Noise sigma=2.0 Identik) ---\")\nfor span_name, hi_x in [(\"Rentang Sempit [0, 2] \", 2.0), (\"Rentang Lebar  [0, 20]\", 20.0)]:\n    xr = rng.uniform(0.0, hi_x, size=300)\n    yr = 3.0 + 1.5 * xr + rng.normal(0.0, 2.0, size=300)\n    Xr = np.column_stack([np.ones(300), xr])\n    yh = Xr @ np.linalg.lstsq(Xr, yr, rcond=None)[0]\n    rmse = float(np.sqrt(np.mean((yr - yh) ** 2)))\n    r2 = float(1.0 - np.sum((yr - yh) ** 2) / np.sum((yr - yr.mean()) ** 2))\n    print(f\"{span_name} -> RMSE={rmse:.4f} (identik) | R^2={r2:.4f}\")",
          "expectedOutput": "=== Verifikasi Monte Carlo BLUE Gauss-Markov (2500 Trial, Error Uniform Non-Gaussian) ===\nTeoretis Var(beta1_OLS)   = 0.009364\n1. OLS (BLUE)             -> mean=2.4041 | emp_var=0.009662 (ratio=1.00x)\n2. Weighted Linear Unbias -> mean=2.4063 | emp_var=0.012305 (ratio=1.27x)\n3. Wald Split-Half Linear -> mean=2.4030 | emp_var=0.013199 (ratio=1.37x)\n--- Jebakan Range Inflation R^2 (Slope=1.5, Noise sigma=2.0 Identik) ---\nRentang Sempit [0, 2]  -> RMSE=1.9528 (identik) | R^2=0.1986\nRentang Lebar  [0, 20] -> RMSE=1.9230 (identik) | R^2=0.9438",
          "actualOutput": "=== Verifikasi Monte Carlo BLUE Gauss-Markov (2500 Trial, Error Uniform Non-Gaussian) ===\nTeoretis Var(beta1_OLS)   = 0.009364\n1. OLS (BLUE)             -> mean=2.4041 | emp_var=0.009662 (ratio=1.00x)\n2. Weighted Linear Unbias -> mean=2.4063 | emp_var=0.012305 (ratio=1.27x)\n3. Wald Split-Half Linear -> mean=2.4030 | emp_var=0.013199 (ratio=1.37x)\n--- Jebakan Range Inflation R^2 (Slope=1.5, Noise sigma=2.0 Identik) ---\nRentang Sempit [0, 2]  -> RMSE=1.9528 (identik) | R^2=0.1986\nRentang Lebar  [0, 20] -> RMSE=1.9230 (identik) | R^2=0.9438",
