          "filename": "06_2_leverage_cooks_svd.py",
          "code": "import numpy as np\n\ndef audit_point(x_base: np.ndarray, y_base: np.ndarray, x_new: float, y_new: float):\n    x_all = np.append(x_base, x_new)\n    y_all = np.append(y_base, y_new)\n    X = np.column_stack([np.ones(len(x_all)), x_all])\n    n, p = X.shape\n    # Hitung Leverage h_ii via Thin SVD (hemat RAM O(Np), ZERO matriks NxN!)\n    U, s, Vt = np.linalg.svd(X, full_matrices=False)\n    h = np.sum(U ** 2, axis=1)\n    beta_hat = Vt.T @ ((U.T @ y_all) / s)\n    resid = y_all - X @ beta_hat\n    s2 = float(np.sum(resid ** 2) / (n - p))\n    stud = resid / np.sqrt(s2 * (1.0 - h))\n    cooks = (resid ** 2 / (p * s2)) * (h / ((1.0 - h) ** 2))\n    # Verifikasi identitas Leave-One-Out eksak pada titik uji (baris terakhir)\n    beta_loo = np.linalg.lstsq(X[:-1], y_all[:-1], rcond=None)[0]\n    diff_yhat = X @ (beta_hat - beta_loo)\n    d_loo_exact = float(np.dot(diff_yhat, diff_yhat) / (p * s2))\n    return float(h.sum()), float(h[-1]), float(stud[-1]), float(cooks[-1]), d_loo_exact, float(beta_hat[1])\n\nrng = np.random.default_rng(42)\nn_base = 59\nx0 = rng.uniform(1.0, 10.0, size=n_base)\ny0 = 2.0 + 1.8 * x0 + rng.normal(0.0, 1.0, size=n_base)\n\nprint(f\"=== Audit Leverage (SVD O(Np)) & Cook's Distance (n=60, p=2, batas 4/n={4/60:.4f}, slope*=1.80) ===\")\nprint(f\"{'Kasus Titik Tambahan':<24s} | {'h_ii':>6s} | {'r_i (stud)':>10s} | {'Cook D_i':>8s} | {'D_i LOO':>8s} | {'Slope':>6s}\")\nprint(\"-\" * 78)\n\ncases = [\n    (\"1. Titik Normal\", 5.5, 2.0 + 1.8 * 5.5 + 0.3),\n    (\"2. Vertical Outlier\", 5.5, 2.0 + 1.8 * 5.5 + 9.0),\n    (\"3. Good High-Leverage\", 24.0, 2.0 + 1.8 * 24.0 + 0.2),\n    (\"4. Bad High-Leverage\", 24.0, 2.0 + 1.8 * 24.0 - 18.0),\n]\nfor label, xv, yv in cases:\n    tr_h, h_i, r_i, d_i, d_loo, slp = audit_point(x0, y0, xv, yv)\n    print(f\"{label:<24s} | {h_i:6.4f} | {r_i:+10.4f} | {d_i:8.4f} | {d_loo:8.4f} | {slp:6.3f}\")\nprint(f\"Verifikasi identitas trace(H) = sum(h_ii) = {tr_h:.4f} (eksak = p = 2)\")",
          "expectedOutput": "=== Audit Leverage (SVD O(Np)) & Cook's Distance (n=60, p=2, batas 4/n=0.0667, slope*=1.80) ===\nKasus Titik Tambahan     |   h_ii | r_i (stud) | Cook D_i |  D_i LOO |  Slope\n------------------------------------------------------------------------------\n1. Titik Normal          | 0.0168 |    +0.6408 |   0.0035 |   0.0035 |  1.858\n2. Vertical Outlier      | 0.0168 |    +6.3916 |   0.3494 |   0.3494 |  1.852\n3. Good High-Leverage    | 0.4781 |    -0.6196 |   0.1758 |   0.1758 |  1.841\n4. Bad High-Leverage     | 0.4781 |    -6.9869 |  22.3555 |  22.3555 |  1.373\nVerifikasi identitas trace(H) = sum(h_ii) = 2.0000 (eksak = p = 2)",
          "actualOutput": "=== Audit Leverage (SVD O(Np)) & Cook's Distance (n=60, p=2, batas 4/n=0.0667, slope*=1.80) ===\nKasus Titik Tambahan     |   h_ii | r_i (stud) | Cook D_i |  D_i LOO |  Slope\n------------------------------------------------------------------------------\n1. Titik Normal          | 0.0168 |    +0.6408 |   0.0035 |   0.0035 |  1.858\n2. Vertical Outlier      | 0.0168 |    +6.3916 |   0.3494 |   0.3494 |  1.852\n3. Good High-Leverage    | 0.4781 |    -0.6196 |   0.1758 |   0.1758 |  1.841\n4. Bad High-Leverage     | 0.4781 |    -6.9869 |  22.3555 |  22.3555 |  1.373\nVerifikasi identitas trace(H) = sum(h_ii) = 2.0000 (eksak = p = 2)",
