          "code": "import numpy as np\nfrom sklearn.linear_model import LinearRegression\n\ndef compute_vif_table(X_mat: np.ndarray, names: list[str]) -> dict[str, float]:\n    vifs = {}\n    for j, name in enumerate(names):\n        others = np.delete(X_mat, j, axis=1)\n        r2_j = LinearRegression().fit(others, X_mat[:, j]).score(others, X_mat[:, j])\n        vifs[name] = float(1.0 / max(1.0 - r2_j, 1e-12))\n    return vifs\n\nrng = np.random.default_rng(99)\nn = 250\n# Simulasi Marketing Mix Modeling (MMM): semua efek kanal SEJATI bernilai POSITIF!\nsearch_ads = rng.uniform(10.0, 100.0, size=n)\nimpresi_sosmed = rng.uniform(20.0, 200.0, size=n)\n# Kolinearitas tinggi: klik_sosmed ~ 0.05 * impresi_sosmed + noise sangat kecil (rho > 0.995)\nklik_sosmed = 0.05 * impresi_sosmed + rng.normal(0.0, 0.25, size=n)\nemail_promo = rng.uniform(5.0, 50.0, size=n)\n\n# Penjualan sejati: search (+2.4), impresi (+1.1), email (+1.8), klik tidak menambah sinyal mandiri\ny = 50.0 + 2.4 * search_ads + 1.1 * impresi_sosmed + 1.8 * email_promo + rng.normal(0.0, 12.0, size=n)\n\n# Tambahkan 2 anomali high-leverage (logging bug: impresi tinggi tapi penjualan tercatat 0)\nimpresi_bad = impresi_sosmed.copy()\nklik_bad = klik_sosmed.copy()\ny_bad = y.copy()\nimpresi_bad[-2:] = [420.0, 450.0]\nklik_bad[-2:] = [24.0, 26.0]\ny_bad[-2:] = [60.0, 55.0]\n\nnames_raw = [\"search_ads\", \"impresi_sosmed\", \"klik_sosmed\", \"email_promo\"]\nX_raw = np.column_stack([search_ads, impresi_bad, klik_bad, email_promo])\n\n# 1. Audit VIF & Cook's Distance pada data mentah\nvifs_raw = compute_vif_table(X_raw, names_raw)\nols_raw = LinearRegression().fit(X_raw, y_bad)\n\nX_aug = np.column_stack([np.ones(n), X_raw])\nU, s, Vt = np.linalg.svd(X_aug, full_matrices=False)\nh = np.sum(U ** 2, axis=1)\ne_raw = y_bad - ols_raw.predict(X_raw)\ns2_raw = float(np.sum(e_raw ** 2) / (n - X_aug.shape[1]))\ncooks_raw = (e_raw ** 2 / (X_aug.shape[1] * s2_raw)) * (h / ((1.0 - h) ** 2))\n\n# 2. Mitigasi Produksi: buang fitur VIF > 10 (klik_sosmed) & karantina Cook's D > 4/n\nkeep_mask = cooks_raw <= (4.0 / n)\nX_clean = np.column_stack([search_ads, impresi_bad, email_promo])[keep_mask]\ny_clean = y_bad[keep_mask]\nnames_clean = [\"search_ads\", \"impresi_sosmed\", \"email_promo\"]\nvifs_clean = compute_vif_table(X_clean, names_clean)\nols_clean = LinearRegression().fit(X_clean, y_clean)\n\nprint(\"=== Audit Produksi: Sign Flip Kolinearitas (VIF) + High-Leverage Outlier ===\")\nprint(\"1. Sebelum Audit (VIF mentah & Koefisien OLS Mentah):\")\nfor nm, c in zip(names_raw, ols_raw.coef_):\n    print(f\"   {nm:<16s} | VIF = {vifs_raw[nm]:7.2f} | coef = {c:+8.4f}\")\nprint(f\"   Max Cook's D = {cooks_raw.max():.3f} | Jumlah titik Cook D > 4/n = {int((~keep_mask).sum())}\")\n\nprint(\"2. Sesudah Audit (Drop klik_sosmed + Karantina Anomali Cook D > 4/n):\")\ntrue_map = {\"search_ads\": 2.4, \"impresi_sosmed\": 1.1, \"email_promo\": 1.8}\nfor nm, c in zip(names_clean, ols_clean.coef_):\n    print(f\"   {nm:<16s} | VIF = {vifs_clean[nm]:7.2f} | coef = {c:+8.4f} (sejati = {true_map[nm]:+.1f})\")",
