          "title": "First-Principles NumPy: Huber IRLS vs RANSAC & Ledakan Iterasi k",
          "language": "python",
          "filename": "06_3_huber_irls_ransac_scratch.py",
          "code": "import numpy as np\n\ndef huber_irls(X: np.ndarray, y: np.ndarray, delta: float = 1.345, max_iter: int = 50, tol: float = 1e-6):\n    # Inisialisasi dari OLS; estimasi skala robust MAD = 1.4826 * median(|r - median(r)|)\n    beta = np.linalg.lstsq(X, y, rcond=None)[0]\n    for _ in range(max_iter):\n        r = y - X @ beta\n        mad = float(np.median(np.abs(r - np.median(r))))\n        sigma = max(1.4826 * mad, 1e-6)\n        u = np.abs(r) / sigma\n        w = np.where(u <= delta, 1.0, delta / np.maximum(u, 1e-12))\n        Xw = X * w[:, None]\n        beta_new = np.linalg.lstsq(Xw, w * y, rcond=None)[0]\n        if np.linalg.norm(beta_new - beta) < tol:\n            beta = beta_new\n            break\n        beta = beta_new\n    return beta\n\ndef ransac_scratch(X: np.ndarray, y: np.ndarray, threshold: float, n_trials: int = 120, seed: int = 42):\n    rng_loc = np.random.default_rng(seed)\n    n, p = X.shape\n    best_inliers = np.zeros(n, dtype=bool)\n    for _ in range(n_trials):\n        idx = rng_loc.choice(n, size=p, replace=False)\n        Xs, ys = X[idx], y[idx]\n        if np.linalg.matrix_rank(Xs) < p:\n            continue\n        b_cand = np.linalg.solve(Xs, ys)\n        inliers = np.abs(y - X @ b_cand) <= threshold\n        if inliers.sum() > best_inliers.sum():\n            best_inliers = inliers\n    # Refit OLS bersih pada seluruh consensus set inliers terbaik\n    beta_refit = np.linalg.lstsq(X[best_inliers], y[best_inliers], rcond=None)[0]\n    return beta_refit, int(best_inliers.sum())\n\nrng = np.random.default_rng(42)\nn = 200\nx_clean = rng.uniform(0.0, 10.0, size=n)\nbeta_true = np.array([3.0, 2.0])\ny_clean = beta_true[0] + beta_true[1] * x_clean + rng.normal(0.0, 0.8, size=n)\n\n# Skenario A: 15% Vertical Y-Outliers\nx_a, y_a = x_clean.copy(), y_clean.copy()\ny_a[:30] += rng.uniform(25.0, 50.0, size=30)\nX_a = np.column_stack([np.ones(n), x_a])\n\n# Skenario B: 25% Adversarial High-Leverage (X & Y ekstrem bersamaan!)\nx_b, y_b = x_clean.copy(), y_clean.copy()\nx_b[:50] = rng.uniform(22.0, 28.0, size=50)\ny_b[:50] = rng.uniform(-15.0, -5.0, size=50)\nX_b = np.column_stack([np.ones(n), x_b])\n\nprint(\"=== First-Principles: OLS vs Huber IRLS vs RANSAC (beta_true = [3.0, 2.0]) ===\")\nfor label, Xm, ym in [(\"A. 15% Vertical Y-Outliers\", X_a, y_a), (\"B. 25% Bad X-Leverage Outliers\", X_b, y_b)]:\n    b_ols = np.linalg.lstsq(Xm, ym, rcond=None)[0]\n    b_hub = huber_irls(Xm, ym, delta=1.345)\n    b_ran, n_in = ransac_scratch(Xm, ym, threshold=2.5, n_trials=150)\n    print(f\"--- {label} ---\")\n    print(f\"  OLS        : intercept={b_ols[0]:+6.2f}, slope={b_ols[1]:+6.3f} | L2 err={np.linalg.norm(b_ols - beta_true):.3f}\")\n    print(f\"  Huber IRLS : intercept={b_hub[0]:+6.2f}, slope={b_hub[1]:+6.3f} | L2 err={np.linalg.norm(b_hub - beta_true):.3f}\")\n    print(f\"  RANSAC     : intercept={b_ran[0]:+6.2f}, slope={b_ran[1]:+6.3f} | L2 err={np.linalg.norm(b_ran - beta_true):.3f} (inliers={n_in}/{n})\")\n\n# Tabel Ledakan Kombinatorial Iterasi Minimum RANSAC (eps=0.40, p=0.99)\nprint(\"--- Ledakan Iterasi Minimum RANSAC k = ceil(log(1-p)/log(1-(1-eps)^s)), eps=40%, p=99% ---\")\neps_out, p_conf = 0.40, 0.99\nfor s_dim in (2, 5, 10, 15, 20):\n    k_req = int(np.ceil(np.log(1.0 - p_conf) / np.log(1.0 - (1.0 - eps_out) ** s_dim)))\n    print(f\"  Minimal subset s={s_dim:2d} (d={s_dim-1:2d}) -> k_min = {k_req:,d} iterasi\")",
          "expectedOutput": "=== First-Principles: OLS vs Huber IRLS vs RANSAC (beta_true = [3.0, 2.0]) ===\n--- A. 15% Vertical Y-Outliers ---\n  OLS        : intercept= +6.61, slope=+2.382 | L2 err=3.631\n  Huber IRLS : intercept= +2.80, slope=+2.050 | L2 err=0.210\n  RANSAC     : intercept= +2.76, slope=+2.055 | L2 err=0.243 (inliers=170/200)\n--- B. 25% Bad X-Leverage Outliers ---\n  OLS        : intercept=+15.72, slope=-0.887 | L2 err=13.043\n  Huber IRLS : intercept=+15.10, slope=-0.885 | L2 err=12.440\n  RANSAC     : intercept= +2.86, slope=+2.042 | L2 err=0.146 (inliers=150/200)\n--- Ledakan Iterasi Minimum RANSAC k = ceil(log(1-p)/log(1-(1-eps)^s)), eps=40%, p=99% ---\n  Minimal subset s= 2 (d= 1) -> k_min = 11 iterasi\n  Minimal subset s= 5 (d= 4) -> k_min = 57 iterasi\n  Minimal subset s=10 (d= 9) -> k_min = 760 iterasi\n  Minimal subset s=15 (d=14) -> k_min = 9,793 iterasi\n  Minimal subset s=20 (d=19) -> k_min = 125,955 iterasi",
