          "code": "import numpy as np\nfrom sklearn.linear_model import HuberRegressor, LinearRegression, RANSACRegressor\n\nrng = np.random.default_rng(21)\nn = 120\nx = rng.uniform(0.0, 10.0, size=n)\ny_base = 2.0 + 3.0 * x + rng.normal(0.0, 0.9, size=n)\n\n# 1. Empirical Influence Curve & Breakdown Point 0% OLS (1 titik tunggal digeser!)\nprint(\"=== Empirical Influence Curve: Geser 1 Titik Outlier y_0 dari 10 -> 100.000 (slope*=3.0) ===\")\nprint(f\"{'y_outlier':>10s} | {'OLS slope':>11s} | {'Huber slope':>12s} | {'RANSAC slope':>12s}\")\nprint(\"-\" * 54)\n\nX_mat = x[:, None]\nfor y_spike in (10.0, 100.0, 1_000.0, 10_000.0, 100_000.0):\n    y_mod = y_base.copy()\n    y_mod[0] = y_spike\n    s_ols = float(LinearRegression().fit(X_mat, y_mod).coef_[0])\n    s_hub = float(HuberRegressor(epsilon=1.35, max_iter=300).fit(X_mat, y_mod).coef_[0])\n    s_ran = float(RANSACRegressor(residual_threshold=3.0, random_state=42).fit(X_mat, y_mod).estimator_.coef_[0])\n    print(f\"{y_spike:10.0f} | {s_ols:+11.3f} | {s_hub:+12.4f} | {s_ran:+12.4f}\")\n\n# 2. Trade-off Efisiensi Gaussian vs Ketahanan Outlier pada parameter epsilon Huber\nprint(\"--- Trade-Off Parameter epsilon HuberRegressor (15 Simulasi Monte Carlo) ---\")\nfor eps_val in (1.05, 1.35, 2.0, 5.0):\n    errs_clean, errs_dirty = [], []\n    for t in range(15):\n        rt = np.random.default_rng(100 + t)\n        xt = rt.uniform(0.0, 10.0, size=70)\n        yt_clean = 2.0 + 3.0 * xt + rt.normal(0.0, 1.0, size=70)\n        yt_dirty = yt_clean.copy()\n        yt_dirty[:9] += 30.0\n        b_c = float(HuberRegressor(epsilon=eps_val, max_iter=120).fit(xt[:, None], yt_clean).coef_[0])\n        b_d = float(HuberRegressor(epsilon=eps_val, max_iter=120).fit(xt[:, None], yt_dirty).coef_[0])\n        errs_clean.append((b_c - 3.0) ** 2)\n        errs_dirty.append((b_d - 3.0) ** 2)\n    print(f\"epsilon={eps_val:4.2f} -> Clean Slope RMSE={np.sqrt(np.mean(errs_clean)):.4f} | 13%-Outlier Slope RMSE={np.sqrt(np.mean(errs_dirty)):.4f}\")",
