          "code": "import numpy as np\nfrom scipy.optimize import linprog\nfrom scipy.sparse import csc_matrix, eye, hstack\n\ndef pinball_loss(y_true: np.ndarray, y_pred: np.ndarray, tau: float) -> float:\n    u = y_true - y_pred\n    return float(np.mean(np.maximum(tau * u, (tau - 1.0) * u)))\n\ndef quantile_regression_lp(X: np.ndarray, y: np.ndarray, tau: float) -> np.ndarray:\n    \"\"\"\n    Formulasi eksak Linear Programming (Koenker & Bassett, 1978) via HiGHS:\n    min_{beta+, beta-, u, v}  sum_i (tau * u_i + (1 - tau) * v_i)\n    s.t.  X (beta+ - beta-) + u - v = y,   beta+, beta-, u, v >= 0\n    \"\"\"\n    n, p = X.shape\n    c = np.concatenate([np.zeros(2 * p), np.full(n, tau), np.full(n, 1.0 - tau)])\n    I_n = eye(n, format=\"csc\")\n    X_sp = csc_matrix(X)\n    A_eq = hstack([X_sp, -X_sp, I_n, -I_n], format=\"csc\")\n    res = linprog(c, A_eq=A_eq, b_eq=y, bounds=(0, None), method=\"highs\")\n    if not res.success:\n        raise RuntimeError(f\"LP gagal konvergen: {res.message}\")\n    beta_pos = res.x[:p]\n    beta_neg = res.x[p:2 * p]\n    return beta_pos - beta_neg\n\nrng = np.random.default_rng(42)\nn_tr, n_te = 260, 240\nn_all = n_tr + n_te\n\n# Simulasi ETA Pengiriman Logistik (menit): jarak (km), jam_sibuk (0/1), hujan (0..1)\njarak = rng.uniform(1.0, 15.0, size=n_all)\nsibuk = rng.binomial(1, 0.35, size=n_all).astype(float)\nhujan = rng.uniform(0.0, 1.0, size=n_all)\n\n# Delay miring kanan (Log-Normal/Gamma) & heteroskedastik (tumbuh bersama jarak & hujan!)\nbase_eta = 8.0 + 2.6 * jarak + 5.5 * sibuk + 4.0 * hujan\nskew_scale = 0.8 + 0.45 * jarak + 3.5 * hujan\ndelay = rng.gamma(shape=2.2, scale=skew_scale, size=n_all)\neta = base_eta + delay\n\nX_all = np.column_stack([np.ones(n_all), jarak, sibuk, hujan])\nX_tr, X_te = X_all[:n_tr], X_all[n_tr:]\ny_tr, y_te = eta[:n_tr], eta[n_tr:]\n\n# Bandingkan OLS Mean vs Linear Programming Quantile (P10, P50, P90)\nbeta_ols = np.linalg.lstsq(X_tr, y_tr, rcond=None)[0]\npred_ols = X_te @ beta_ols\n\nprint(\"=== First-Principles Linear Programming (HiGHS) Quantile Regression untuk ETA Logistik ===\")\nprint(f\"OLS (MSE Mean) -> Test SLA Breach (y > yhat) = {np.mean(y_te > pred_ols)*100:5.2f}% | P90 Pinball = {pinball_loss(y_te, pred_ols, 0.90):.3f}\")\n\nfor tau in (0.10, 0.50, 0.90):\n    b_q = quantile_regression_lp(X_tr, y_tr, tau=tau)\n    pred_q = X_te @ b_q\n    cov = float(np.mean(y_te <= pred_q))\n    pl = pinball_loss(y_te, pred_q, tau)\n    print(f\"LP Quantile tau={tau:.2f} -> Test Coverage P(y<=q) = {cov*100:5.2f}% | Breach = {(1-cov)*100:5.2f}% | Pinball = {pl:.3f} | coef_jarak={b_q[1]:.2f}\")",
          "expectedOutput": "=== First-Principles Linear Programming (HiGHS) Quantile Regression untuk ETA Logistik ===\nOLS (MSE Mean) -> Test SLA Breach (y > yhat) = 47.92% | P90 Pinball = 4.500\nLP Quantile tau=0.10 -> Test Coverage P(y<=q) =  9.17% | Breach = 90.83% | Pinball = 1.234 | coef_jarak=2.91\nLP Quantile tau=0.50 -> Test Coverage P(y<=q) = 45.83% | Breach = 54.17% | Pinball = 3.858 | coef_jarak=3.52\nLP Quantile tau=0.90 -> Test Coverage P(y<=q) = 85.00% | Breach = 15.00% | Pinball = 2.564 | coef_jarak=4.15",
          "actualOutput": "=== First-Principles Linear Programming (HiGHS) Quantile Regression untuk ETA Logistik ===\nOLS (MSE Mean) -> Test SLA Breach (y > yhat) = 47.92% | P90 Pinball = 4.500\nLP Quantile tau=0.10 -> Test Coverage P(y<=q) =  9.17% | Breach = 90.83% | Pinball = 1.234 | coef_jarak=2.91\nLP Quantile tau=0.50 -> Test Coverage P(y<=q) = 45.83% | Breach = 54.17% | Pinball = 3.858 | coef_jarak=3.52\nLP Quantile tau=0.90 -> Test Coverage P(y<=q) = 85.00% | Breach = 15.00% | Pinball = 2.564 | coef_jarak=4.15",
          "explanation": "Merumuskan dan menyelesaikan Quantile Regression (P10, P50, P90) sebagai Program Linear eksak lewat scipy.optimize.linprog(method='highs') pada data ETA miring kanan heteroskedastik.",
