          "id": "code-ml-06-4-ch06_4_diag",
          "title": "Audit SLA Produksi: OLS+Margin vs Quantile P90, Crossing & Biaya Bisnis",
          "language": "python",
          "filename": "06_4_sla_crossing_cost_audit.py",
          "code": "import numpy as np\nfrom sklearn.ensemble import HistGradientBoostingRegressor\nfrom sklearn.linear_model import LinearRegression, QuantileRegressor\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(314)\nn = 800\njarak = rng.uniform(1.0, 18.0, size=n)\nhujan = rng.binomial(1, 0.30, size=n).astype(float)\nsibuk = rng.binomial(1, 0.35, size=n).astype(float)\n\n# Heteroskedastisitas ekstrem: jarak dekat presisi tinggi, jarak jauh+hujan ekor kanan sangat panjang\nscale = 0.35 + 0.55 * jarak + 5.5 * hujan * sibuk\neta = 8.0 + 2.2 * jarak + 3.5 * hujan + rng.gamma(shape=2.0, scale=scale, size=n)\n\nX = np.column_stack([jarak, hujan, sibuk, hujan * sibuk])\nX_tr, X_te, y_tr, y_te = train_test_split(X, eta, test_size=0.30, random_state=42)\n\n# Strategi 1 (Anti-Pattern): OLS Mean + Buffer Konstan agar global coverage ~ 90%\nols = LinearRegression().fit(X_tr, y_tr)\nconst_margin = float(np.quantile(y_tr - ols.predict(X_tr), 0.90))\neta_ols_margin = ols.predict(X_te) + const_margin\n\n# Strategi 2 (Production-Safe): QuantileRegressor P90 (adaptif heteroskedastisitas!)\nq90_lin = QuantileRegressor(quantile=0.90, alpha=0.0, solver=\"highs\").fit(X_tr, y_tr)\neta_q90 = q90_lin.predict(X_te)\n\n# Audit Fenomena Quantile Crossing pada model pohon independen (tau berdekatan: 0.40, 0.50, 0.60)\nq_tree_raw = np.column_stack([\n    HistGradientBoostingRegressor(\n        loss=\"quantile\", quantile=tau, max_iter=65, max_depth=5,\n        min_samples_leaf=10, learning_rate=0.08, random_state=42\n    ).fit(X_tr, y_tr).predict(X_te)\n    for tau in (0.40, 0.50, 0.60)\n])\ncrossings_before = int(np.sum((q_tree_raw[:, 0] > q_tree_raw[:, 1]) | (q_tree_raw[:, 1] > q_tree_raw[:, 2])))\nq_tree_sorted = np.sort(q_tree_raw, axis=1)\ncrossings_after = int(np.sum((q_tree_sorted[:, 0] > q_tree_sorted[:, 1]) | (q_tree_sorted[:, 1] > q_tree_sorted[:, 2])))\n\n# Evaluasi Biaya Bisnis Asimetris Linear (Rp/menit):\n# Terlambat -> biaya kompensasi & churn Rp 9.000/menit; terlalu pesimis -> Rp 1.000/menit\n# Rasio optimal teoretis: tau* = 9.000 / (9.000 + 1.000) = 0.90 (P90!)\ndef business_cost_per_order(y_actual, eta_promised):\n    late_cost = 9_000.0 * np.maximum(y_actual - eta_promised, 0.0)\n    buffer_cost = 1_000.0 * np.maximum(eta_promised - y_actual, 0.0)\n    return float(np.mean(late_cost + buffer_cost))\n\nshort_mask = X_te[:, 0] <= 5.0\nlong_mask = X_te[:, 0] >= 13.0\n\nprint(\"=== Audit Produksi SLA: OLS+Margin Konstan vs Quantile P90 & Quantile Crossing ===\")\nprint(f\"Quantile Crossing (HGB 0.40/0.50/0.60): Sebelum Sort = {crossings_before}/{len(y_te)} | Sesudah Sort = {crossings_after}/{len(y_te)}\")\nprint(f\"OLS + Margin (+{const_margin:.1f}m) -> Global Breach={np.mean(y_te > eta_ols_margin)*100:4.1f}% | Dekat(<=5km)={np.mean(y_te[short_mask] > eta_ols_margin[short_mask])*100:4.1f}% | Jauh(>=13km)={np.mean(y_te[long_mask] > eta_ols_margin[long_mask])*100:4.1f}%\")\nprint(f\"Quantile P90 (LP)     -> Global Breach={np.mean(y_te > eta_q90)*100:4.1f}% | Dekat(<=5km)={np.mean(y_te[short_mask] > eta_q90[short_mask])*100:4.1f}% | Jauh(>=13km)={np.mean(y_te[long_mask] > eta_q90[long_mask])*100:4.1f}%\")\nprint(f\"Over-Buffer Jarak Dekat (<=5km): OLS+Margin={np.mean(np.maximum(eta_ols_margin[short_mask]-y_te[short_mask], 0)):.2f}m vs Quantile P90={np.mean(np.maximum(eta_q90[short_mask]-y_te[short_mask], 0)):.2f}m\")\nprint(f\"Biaya Bisnis Ekspektasi / Order: OLS+Margin = Rp {business_cost_per_order(y_te, eta_ols_margin):,.0f} vs Quantile P90 = Rp {business_cost_per_order(y_te, eta_q90):,.0f}\")",
          "expectedOutput": "=== Audit Produksi SLA: OLS+Margin Konstan vs Quantile P90 & Quantile Crossing ===\nQuantile Crossing (HGB 0.40/0.50/0.60): Sebelum Sort = 38/240 | Sesudah Sort = 0/240\nOLS + Margin (+11.8m) -> Global Breach= 4.6% | Dekat(<=5km)= 0.0% | Jauh(>=13km)= 5.1%\nQuantile P90 (LP)     -> Global Breach= 7.5% | Dekat(<=5km)=13.6% | Jauh(>=13km)= 1.3%\nOver-Buffer Jarak Dekat (<=5km): OLS+Margin=11.69m vs Quantile P90=4.64m\nBiaya Bisnis Ekspektasi / Order: OLS+Margin = Rp 17,765 vs Quantile P90 = Rp 16,410",
          "actualOutput": "=== Audit Produksi SLA: OLS+Margin Konstan vs Quantile P90 & Quantile Crossing ===\nQuantile Crossing (HGB 0.40/0.50/0.60): Sebelum Sort = 38/240 | Sesudah Sort = 0/240\nOLS + Margin (+11.8m) -> Global Breach= 4.6% | Dekat(<=5km)= 0.0% | Jauh(>=13km)= 5.1%\nQuantile P90 (LP)     -> Global Breach= 7.5% | Dekat(<=5km)=13.6% | Jauh(>=13km)= 1.3%\nOver-Buffer Jarak Dekat (<=5km): OLS+Margin=11.69m vs Quantile P90=4.64m\nBiaya Bisnis Ekspektasi / Order: OLS+Margin = Rp 17,765 vs Quantile P90 = Rp 16,410",
